content:
===== FILE: styles.css =====
:root {
  --bg: #f9f7f4;
  --surface: #ffffff;
  --surface-alt: #f2ece4;
  --text: #221f1d;
  --text-muted: #6e665f;
  --accent: #7a4b3a;
  --accent-hover: #5e3729;
  --border: #e5ded6;
  --success: #3b6e52;
  --danger: #a94438;
  --font-sans: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", -apple-system, BlinkMacSystemFont, sans-serif;
  --font-serif: "Songti SC", "STSong", "Noto Serif SC", serif;
  --shadow: 0 8px 24px rgba(34, 31, 29, 0.06);
  --radius: 4px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color 0.2s ease;
}

button, input, select {
  font-family: inherit;
  font-size: inherit;
}

.container {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Announcement Bar */
.topbar {
  background-color: var(--text);
  color: #f4f0ea;
  font-size: 13px;
  text-align: center;
  padding: 9px 16px;
  letter-spacing: 0.5px;
}

/* Header & Navigation */
.site-header {
  background-color: rgba(249, 247, 244, 0.95);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 76px;
}

.brand-logo {
  font-family: var(--font-serif);
  font-size: 28px;
  font-weight: 600;
  letter-spacing: 4px;
  color: var(--text);
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.brand-sub {
  font-family: var(--font-sans);
  font-size: 12px;
  letter-spacing: 1px;
  color: var(--text-muted);
  font-weight: 400;
}

.main-nav {
  display: flex;
  gap: 36px;
}

.main-nav a {
  font-size: 15px;
  color: var(--text);
  padding: 8px 0;
  position: relative;
}

.main-nav a:hover,
.main-nav a.active {
  color: var(--accent);
  font-weight: 500;
}

.main-nav a.active::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background-color: var(--accent);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 20px;
}

.search-box {
  display: flex;
  align-items: center;
  background-color: var(--surface);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 5px 14px;
}

.search-box input {
  border: none;
  background: transparent;
  outline: none;
  font-size: 13px;
  width: 150px;
  color: var(--text);
}

.search-box button {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--text-muted);
  font-size: 13px;
}

.cart-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  padding: 8px 14px;
  border: 1px solid var(--border);
  border-radius: 20px;
  background-color: var(--surface);
  transition: all 0.2s;
}

.cart-link:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.cart-badge {
  background-color: var(--accent);
  color: #fff;
  font-size: 12px;
  min-width: 20px;
  height: 20px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 6px;
  font-weight: 500;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 28px;
  font-size: 14px;
  font-weight: 500;
  border-radius: var(--radius);
  cursor: pointer;
  transition: all 0.2s ease;
  border: 1px solid transparent;
  letter-spacing: 0.8px;
}

.btn-primary {
  background-color: var(--accent);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--accent-hover);
}

.btn-outline {
  background-color: transparent;
  border-color: var(--text);
  color: var(--text);
}

.btn-outline:hover {
  background-color: var(--text);
  color: #ffffff;
}

.btn-light {
  background-color: var(--surface);
  border-color: var(--border);
  color: var(--text);
}

.btn-light:hover {
  border-color: var(--text);
}

/* Hero Section */
.hero {
  background: linear-gradient(115deg, #ede5dc 0%, #f7f3ee 55%, #e6dbd0 100%);
  border-bottom: 1px solid var(--border);
  padding: 64px 0;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 48px;
  align-items: center;
}

.hero-tag {
  display: inline-block;
  font-size: 13px;
  color: var(--accent);
  background-color: rgba(122, 75, 58, 0.1);
  padding: 4px 12px;
  border-radius: 2px;
  margin-bottom: 18px;
  letter-spacing: 1px;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: 44px;
  line-height: 1.25;
  margin-bottom: 20px;
  color: var(--text);
  font-weight: 600;
}

.hero-desc {
  font-size: 16px;
  color: var(--text-muted);
  margin-bottom: 32px;
  max-width: 520px;
}

.hero-actions {
  display: flex;
  gap: 16px;
}

.hero-visual {
  position: relative;
  background-color: var(--surface);
  padding: 18px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.hero-visual svg {
  width: 100%;
  height: 460px;
  display: block;
  border-radius: 2px;
}

.hero-caption {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 12px;
  font-size: 13px;
  color: var(--text-muted);
}

/* Section Generic */
.section {
  padding: 72px 0;
}

.section-alt {
  background-color: var(--surface-alt);
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 36px;
}

.section-title {
  font-family: var(--font-serif);
  font-size: 28px;
  font-weight: 600;
  color: var(--text);
}

.section-subtitle {
  font-size: 14px;
  color: var(--text-muted);
  margin-top: 6px;
}

/* Category Cards */
.category-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.category-card {
  background-color: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 32px 28px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.category-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow);
}

.category-card h3 {
  font-family: var(--font-serif);
  font-size: 22px;
  margin-bottom: 10px;
}

.category-card p {
  color: var(--text-muted);
  font-size: 14px;
  margin-bottom: 24px;
}

.category-meta {
  font-size: 13px;
  color: var(--accent);
  font-weight: 500;
}

/* Product Grid & Cards */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 28px 24px;
}

.product-card {
  background-color: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow 0.25s ease, transform 0.25s ease;
}

.product-card:hover {
  box-shadow: var(--shadow);
  transform: translateY(-3px);
}

.product-thumb {
  position: relative;
  height: 310px;
  background-color: #f3efeA;
  overflow: hidden;
  display: block;
}

.product-thumb svg {
  width: 100%;
  height: 100%;
  display: block;
}

.product-tag {
  position: absolute;
  top: 12px;
  left: 12px;
  background-color: rgba(34, 31, 29, 0.82);
  color: #fff;
  font-size: 12px;
  padding: 3px 10px;
  border-radius: 2px;
}

.product-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.product-cat {
  font-size: 12px;
  color: var(--text-muted);
  margin-bottom: 4px;
}

.product-title {
  font-size: 15px;
  font-weight: 500;
  color: var(--text);
  margin-bottom: 6px;
  line-height: 1.4;
}

.product-title:hover {
  color: var(--accent);
}

.product-fabric {
  font-size: 12px;
  color: var(--text-muted);
  margin-bottom: 12px;
}

.product-meta-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: auto;
  padding-top: 10px;
  border-top: 1px solid #f0ebe5;
}

.product-price {
  font-size: 17px;
  font-weight: 600;
  color: var(--accent);
}

.product-sizes {
  display: flex;
  gap: 4px;
}

.size-pill {
  font-size: 11px;
  padding: 2px 6px;
  border: 1px solid var(--border);
  border-radius: 2px;
  color: var(--text-muted);
  background: var(--bg);
}

.product-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: 12px;
}

.product-actions .btn {
  padding: 8px 10px;
  font-size: 12px;
}

/* Filter Bar (Products Page) */
.filter-bar {
  background-color: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px 24px;
  margin-bottom: 32px;
  display: flex;
  flex-wrap: wrap;
  gap: 20px 36px;
  align-items: center;
  justify-content: space-between;
}

.filter-group {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.filter-label {
  font-size: 13px;
  color: var(--text-muted);
  font-weight: 500;
}

.filter-chip {
  background: transparent;
  border: 1px solid var(--border);
  padding: 6px 14px;
  font-size: 13px;
  border-radius: 20px;
  cursor: pointer;
  color: var(--text);
  transition: all 0.15s;
}

.filter-chip:hover {
  border-color: var(--accent);
}

.filter-chip.active {
  background-color: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.sort-select {
  padding: 7px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background-color: var(--bg);
  color: var(--text);
  font-size: 13px;
}

/* Product Detail Layout */
.breadcrumb {
  padding: 20px 0;
  font-size: 13px;
  color: var(--text-muted);
}

.breadcrumb a:hover {
  color: var(--accent);
}

.detail-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 52px;
  margin-bottom: 64px;
}

.gallery-main {
  background-color: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  margin-bottom: 14px;
}

.gallery-main svg {
  width: 100%;
  height: 520px;
  display: block;
}

.gallery-thumbs {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.thumb-btn {
  border: 2px solid var(--border);
  background: var(--surface);
  padding: 8px;
  border-radius: var(--radius);
  cursor: pointer;
  text-align: center;
  font-size: 12px;
  color: var(--text-muted);
}

.thumb-btn.active {
  border-color: var(--accent);
  color: var(--accent);
  font-weight: 500;
}

.detail-info h1 {
  font-family: var(--font-serif);
  font-size: 28px;
  margin-bottom: 8px;
}

.detail-subtitle {
  color: var(--text-muted);
  font-size: 14px;
  margin-bottom: 20px;
}

.detail-price-box {
  background-color: var(--surface-alt);
  padding: 16px 20px;
  border-radius: var(--radius);
  margin-bottom: 24px;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.detail-price {
  font-size: 26px;
  font-weight: 600;
  color: var(--accent);
}

.detail-perk {
  font-size: 13px;
  color: var(--text-muted);
}

.option-block {
  margin-bottom: 22px;
}

.option-header {
  display: flex;
  justify-content: space-between;
  font-size: 14px;
  font-weight: 500;
  margin-bottom: 10px;
}

.option-list {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.opt-btn {
  min-width: 64px;
  padding: 9px 16px;
  border: 1px solid var(--border);
  background-color: var(--surface);
  border-radius: var(--radius);
  cursor: pointer;
  font-size: 14px;
  transition: all 0.15s;
}

.opt-btn:hover {
  border-color: var(--text);
}

.opt-btn.active {
  border-color: var(--accent);
  background-color: var(--accent);
  color: #fff;
}

.qty-control {
  display: inline-flex;
  border: 1px solid var(--border);
  background-color: var(--surface);
  border-radius: var(--radius);
}

.qty-control button {
  width: 38px;
  height: 38px;
  border: none;
  background: none;
  cursor: pointer;
  font-size: 16px;
}

.qty-control input {
  width: 50px;
  text-align: center;
  border: none;
  border-left: 1px solid var(--border);
  border-right: 1px solid var(--border);
  background: transparent;
}

.detail-cta {
  display: flex;
  gap: 16px;
  margin: 28px 0;
}

.detail-cta .btn {
  flex: 1;
  padding: 15px 24px;
  font-size: 15px;
}

.detail-meta-list {
  border-top: 1px solid var(--border);
  padding-top: 20px;
  font-size: 13px;
  color: var(--text-muted);
  display: grid;
  gap: 10px;
}

.detail-meta-list strong {
  color: var(--text);
  display: inline-block;
  width: 84px;
}

/* Size Table */
.size-table-wrap {
  background-color: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 28px;
  margin-bottom: 48px;
}

.size-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 16px;
  font-size: 14px;
}

.size-table th,
.size-table td {
  border: 1px solid var(--border);
  padding: 12px 16px;
  text-align: center;
}

.size-table th {
  background-color: var(--surface-alt);
  font-weight: 500;
}

/* Cart Page */
.cart-layout {
  display: grid;
  grid-template-columns: 1.5fr 0.8fr;
  gap: 36px;
  align-items: start;
}

.cart-box {
  background-color: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
}

.cart-item {
  display: grid;
  grid-template-columns: 96px 1fr auto;
  gap: 20px;
  padding: 20px 0;
  border-bottom: 1px solid var(--border);
  align-items: center;
}

.cart-item:first-child {
  padding-top: 0;
}

.cart-item:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.cart-thumb {
  width: 96px;
  height: 116px;
  background-color: #f3efeA;
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--border);
}

.cart-thumb svg {
  width: 100%;
  height: 100%;
  display: block;
}

.cart-item-title {
  font-size: 16px;
  font-weight: 500;
  margin-bottom: 6px;
  display: inline-block;
}

.cart-item-specs {
  font-size: 13px;
  color: var(--text-muted);
  margin-bottom: 12px;
  display: flex;
  gap: 12px;
  align-items: center;
}

.cart-item-specs select {
  padding: 3px 8px;
  border: 1px solid var(--border);
  border-radius: 2px;
  font-size: 12px;
  background: var(--bg);
}

.cart-item-right {
  text-align: right;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 10px;
}

.cart-item-price {
  font-size: 16px;
  font-weight: 600;
  color: var(--accent);
}

.remove-btn {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 12px;
  cursor: pointer;
  text-decoration: underline;
}

.remove-btn:hover {
  color: var(--danger);
}

.summary-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 14px;
  font-size: 14px;
}

.summary-total {
  border-top: 1px solid var(--border);
  padding-top: 16px;
  margin-top: 16px;
  font-size: 18px;
  font-weight: 600;
}

.promo-group {
  display: flex;
  gap: 8px;
  margin: 18px 0;
}

.promo-group input {
  flex: 1;
  padding: 9px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font-size: 13px;
}

.checkout-form {
  margin-top: 20px;
  border-top: 1px solid var(--border);
  padding-top: 20px;
  display: grid;
  gap: 12px;
}

.checkout-form label {
  font-size: 13px;
  color: var(--text-muted);
  display: block;
  margin-bottom: 4px;
}

.checkout-form input,
.checkout-form select {
  width: 100%;
  padding: 9px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font-size: 14px;
  background: var(--bg);
}

/* Toast Notification */
.toast {
  position: fixed;
  bottom: 28px;
  right: 28px;
  background-color: var(--text);
  color: #fff;
  padding: 14px 22px;
  border-radius: var(--radius);
  font-size: 14px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.18);
  opacity: 0;
  transform: translateY(12px);
  pointer-events: none;
  transition: all 0.25s ease;
  z-index: 999;
}

.toast.show {
  opacity: 1;
  transform: translateY(0);
}

/* Footer */
.site-footer {
  background-color: #221f1d;
  color: #d8d0c7;
  padding: 64px 0 36px;
  margin-top: 60px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1.2fr;
  gap: 40px;
  padding-bottom: 44px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
}

.footer-brand {
  font-family: var(--font-serif);
  font-size: 24px;
  color: #fff;
  letter-spacing: 3px;
  margin-bottom: 12px;
}

.footer-col h4 {
  color: #fff;
  font-size: 15px;
  margin-bottom: 16px;
  font-weight: 500;
}

.footer-col ul {
  list-style: none;
  display: grid;
  gap: 10px;
  font-size: 13px;
}

.footer-col a:hover {
  color: #fff;
}

.footer-bottom {
  padding-top: 24px;
  font-size: 12px;
  color: #968d84;
  display: flex;
  justify-content: space-between;
}

/* Responsive */
@media (max-width: 1080px) {
  .product-grid {
    grid-template-columns: repeat(3, 1fr);
  }
  .hero-grid, .detail-grid, .cart-layout {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .header-inner {
    flex-wrap: wrap;
    height: auto;
    padding: 14px 0;
    gap: 12px;
  }
  .product-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .category-grid, .footer-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .product-grid {
    grid-template-columns: 1fr;
  }
}
