    let currentCat = "全部";
    let currentSize = "全部";

    function applyFilters() {
      const keyword = (document.getElementById("keyword-input").value || "").trim();
      const sortVal = document.getElementById("sort-select").value;

      let list = PRODUCTS.filter(p => {
        const matchCat = currentCat === "全部" || p.category === currentCat;
        const matchSize = currentSize === "全部" || p.sizes.includes(currentSize);
        const matchKw = !keyword || p.name.includes(keyword) || p.fabric.includes(keyword) || p.subcat.includes(keyword);
        return matchCat && matchSize && matchKw;
      });

      if (sortVal === "price-asc") {
        list.sort((a, b) => a.price - b.price);
      } else if (sortVal === "price-desc") {
        list.sort((a, b) => b.price - a.price);
      }

      const grid = document.getElementById("catalog-grid");
      const countEl = document.getElementById("result-count");
      countEl.textContent = `共 ${list.length} 件单品`;

      if (list.length === 0) {
        grid.innerHTML = `
          <div style="grid-column: 1 / -1; text-align:center; padding: 60px 20px; background: var(--surface); border:1px solid var(--border);">
            <p style="font-size: 16px; margin-bottom: 12px;">暂未找到符合当前筛选条件的单品</p>
            <button type="button" class="btn btn-outline" onclick="resetFilters()">重置全部筛选</button>
          </div>
        `;
      } else {
        grid.innerHTML = list.map(createProductCardHTML).join("");
      }
    }

    function resetFilters() {
      currentCat = "全部";
      currentSize = "全部";
      document.getElementById("keyword-input").value = "";
      document.getElementById("sort-select").value = "default";
      document.querySelectorAll("#cat-filters .filter-chip").forEach(b => b.classList.toggle("active", b.dataset.cat === "全部"));
      document.querySelectorAll("#size-filters .filter-chip").forEach(b => b.classList.toggle("active", b.dataset.size === "全部"));
      applyFilters();
    }

    document.addEventListener("DOMContentLoaded", () => {
      const params = new URLSearchParams(window.location.search);
      const urlCat = params.get("cat");
      if (urlCat && ["职场通勤", "日常休闲", "轻社交晚装"].includes(urlCat)) {
        currentCat = urlCat;
      }

      document.querySelectorAll("#cat-filters .filter-chip").forEach(btn => {
        btn.classList.toggle("active", btn.dataset.cat === currentCat);
        btn.addEventListener("click", () => {
          currentCat = btn.dataset.cat;
          document.querySelectorAll("#cat-filters .filter-chip").forEach(b => b.classList.remove("active"));
          btn.classList.add("active");
          applyFilters();
        });
      });

      document.querySelectorAll("#size-filters .filter-chip").forEach(btn => {
        btn.addEventListener("click", () => {
          currentSize = btn.dataset.size;
          document.querySelectorAll("#size-filters .filter-chip").forEach(b => b.classList.remove("active"));
          btn.classList.add("active");
          applyFilters();
        });
      });

      document.getElementById("keyword-input").addEventListener("input", applyFilters);
      applyFilters();
    });
