      colorLabel.textContent = selectedColor;
      colorContainer.innerHTML = currentProduct.colors.map(c => `
        <button type="button" class="opt-btn ${c === selectedColor ? 'active' : ''}" data-color="${c}">${c}</button>
      `).join("");

      colorContainer.querySelectorAll(".opt-btn").forEach(btn => {
        btn.addEventListener("click", () => {
          selectedColor = btn.dataset.color;
          colorLabel.textContent = selectedColor;
          colorContainer.querySelectorAll(".opt-btn").forEach(b => b.classList.remove("active"));
          btn.classList.add("active");
        });
      });

      // Render Sizes
      const sizeContainer = document.getElementById("size-options");
      const sizeLabel = document.getElementById("selected-size-label");
      sizeLabel.textContent = `${selectedSize} 码`;
      sizeContainer.innerHTML = currentProduct.sizes.map(s => `
        <button type="button" class="opt-btn ${s === selectedSize ? 'active' : ''}" data-size="${s}">${s} 码</button>
      `).join("");

      sizeContainer.querySelectorAll(".opt-btn").forEach(btn => {
        btn.addEventListener("click", () => {
          selectedSize = btn.dataset.size;
          sizeLabel.textContent = `${selectedSize} 码`;
          sizeContainer.querySelectorAll(".opt-btn").forEach(b => b.classList.remove("active"));
          btn.classList.add("active");
        });
      });

      // Related items
      const related = PRODUCTS.filter(p => p.id !== currentProduct.id).slice(0, 4);
      document.getElementById("related-grid").innerHTML = related.map(createProductCardHTML).join("");
    });
  </script>
</body>
