  <script src="app.js"></script>
  <script>
    let promoDiscountRate = 0;

    function renderCartPage() {
      const cart = getCart();
      const container = document.getElementById("cart-items-container");

      if (cart.length === 0) {
        container.innerHTML = `
          <div style="text-align: center; padding: 48px 16px;">
            <p style="font-size: 16px; margin-bottom: 14px; color: var(--text-muted);">您的购物袋暂时没有单品</p>
            <a href="products.html" class="btn btn-primary">去挑选心仪女装</a>
          </div>
        `;
      } else {
        container.innerHTML = cart.map((item, idx) => {
          const prod = PRODUCTS.find(p => p.id === item.id) || PRODUCTS[0];
          const sizeOptions = prod.sizes.map(s => `<option value="${s}" ${s === item.size ? 'selected' : ''}>${s}码</option>`).join("");
          return `
            <div class="cart-item">
              <a href="product-detail.html?id=${prod.id}" class="cart-thumb">
                ${renderGarmentSVG(prod)}
              </a>
              <div>
                <a href="product-detail.html?id=${prod.id}" class="cart-item-title">${prod.name}</a>
                <div class="cart-item-specs">
                  <span>颜色：${item.color}</span>
                  <span>尺码：
                    <select onchange="updateItemSize(${idx}, this.value)" aria-label="修改尺码">
                      ${sizeOptions}
                    </select>
                  </span>
                  <span>单价：¥${prod.price}</span>
                </div>
                <div class="qty-control">
                  <button type="button" onclick="updateItemQty(${idx}, -1)" aria-label="减少数量">−</button>
                  <input type="text" value="${item.qty}" readonly aria-label="商品数量">
                  <button type="button" onclick="updateItemQty(${idx}, 1)" aria-label="增加数量">+</button>
                </div>
              </div>
              <div class="cart-item-right">
                <span class="cart-item-price">¥${prod.price * item.qty}</span>
                <button type="button" class="remove-btn" onclick="removeItem(${idx})">移除单品</button>
              </div>
            </div>
          `;
        }).join("");
      }

      calculateSummary(cart);
    }

    function calculateSummary(cart) {
      let totalCount = 0;
      let subtotal = 0;
      cart.forEach(item => {
        const prod = PRODUCTS.find(p => p.id === item.id) || PRODUCTS[0];
        totalCount += Number(item.qty);
        subtotal += prod.price * Number(item.qty);
      });

      const shipping = subtotal === 0 || subtotal >= 399 ? 0 : 18;
      const discount = Math.round(subtotal * promoDiscountRate);
      const finalTotal = Math.max(0, subtotal + shipping - discount);

      document.getElementById("sum-count").textContent = totalCount;
      document.getElementById("sum-subtotal").textContent = `¥${subtotal}`;
      document.getElementById("sum-shipping").textContent = shipping === 0 ? "¥0（顺丰包邮）" : `¥${shipping}`;
      document.getElementById("sum-discount").textContent = `-¥${discount}`;
      document.getElementById("sum-final").textContent = `¥${finalTotal}`;
    }

    function updateItemQty(idx, delta) {
      const cart = getCart();
      if (!cart[idx]) return;
      cart[idx].qty += delta;
      if (cart[idx].qty <= 0) {
        cart.splice(idx, 1);
      }
      saveCart(cart);
      renderCartPage();
    }

    function updateItemSize(idx, newSize) {
      const cart = getCart();
      if (!cart[idx]) return;
      cart[idx].size = newSize;
      saveCart(cart);
      showToast(`已将尺码更新为 ${newSize} 码`);
      renderCartPage();
    }

    function removeItem(idx) {
      const cart = getCart();
      cart.splice(idx, 1);
      saveCart(cart);
      renderCartPage();
    }

    function quickAddFromCart(id, size, color) {
      addToCart(id, size, color, 1);
      renderCartPage();
    }

    function applyPromoCode() {
      const code = (document.getElementById("promo-input").value || "").trim().toUpperCase();
      if (code === "KEYI90" || code === "SHANGHAI") {
        promoDiscountRate = 0.1;
        showToast("已成功使用 9 折礼券码！");
      } else {
        promoDiscountRate = 0;
        showToast("未识别该礼券码，您可尝试输入 KEYI90");
      }
      renderCartPage();
    }

    function handleCheckout(e) {
      e.preventDefault();
      const cart = getCart();
      if (cart.length === 0) {
        showToast("购物袋为空，请先添加心仪商品");
        return;
      }
      const name = document.getElementById("ship-name").value;
      const addr = document.getElementById("ship-city").value;
      const pay = document.getElementById("pay-method").value;
      const finalAmt = document.getElementById("sum-final").textContent;
      const orderNo = "KY202505" + Math.floor(1000 + Math.random() * 9000);

      const confirmBox = document.getElementById("order-confirm-box");
      confirmBox.style.display = "block";
      confirmBox.innerHTML = `
        <strong>订单预订已生成（单号：${orderNo}）</strong><br>
        收货人：${name}<br>
        配送地址：${addr}<br>
        结算金额：${finalAmt}（${pay}）<br>
        上海静安仓正在为您安排蒸汽整烫与顺丰打包。
      `;
      showToast(`订单 ${orderNo} 提交成功！`);
    }

    document.addEventListener("DOMContentLoaded", () => {
      renderCartPage();
    });
  </script>
